import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long h = Long.parseLong(next());
        long w = Long.parseLong(next());
        long[][] matrix = new long[(int) h][(int) w];
        for (int i = 0; i < matrix.length; i++) {
            for (int j = 0; j < matrix[i].length; j++) {
                matrix[i][j] = Long.parseLong(next());
            }
        }

        int rowsCount = (int) h, colsCount = (int) w;
        long[] best = matrix[0].clone();
        long[] next = new long[colsCount];
        for (int i = 1; i < rowsCount; i++) {
            for (int j = 0; j < colsCount; j++) {
                long lowest = best[j];
                if (j > 0) lowest = Math.min(lowest, best[j - 1]);
                if (j + 1 < colsCount) lowest = Math.min(lowest, best[j + 1]);
                next[j] = lowest + matrix[i][j];
            }
            long[] swap = best;
            best = next;
            next = swap;
        }
        long answer = best[0];
        for (long x : best) answer = Math.min(answer, x);
        System.out.println(answer);
    }
}
